#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N;
    int M;
    cin >> N >> M;

    vector<long long> T(M);
    for (auto &t : T) cin >> t;

    for (long long k = 1; k <= 10000; ++k) {
        long long pos = k;

        for (int i = M - 1; i >= 0; --i) {
            pos += (pos - 1) / (T[i] - 1);
            if (pos > N) break;
        }

        if (pos > N) break;
        cout << pos << '\n';
    }

    return 0;
}
